// Step: Allocate Resources (Intelligent Allocation Logic)
const payload = $input.first().json.body || $input.first().json;
const incident = payload.incident || {};
const requested = payload.responsePlan?.resourceAllocation || { ambulances: 2, rescueTeams: 2, drones: 1 };

const allocated = {
  incidentId: incident.id || 'INC-ACTIVE',
  assignedAmbulances: requested.ambulances || 2,
  assignedRescueTeams: requested.rescueTeams || 2,
  assignedDrones: requested.drones || 1,
  priorityZone: incident.primaryLocation?.name || 'Zone A',
  allocationTimestamp: new Date().toISOString(),
  status: 'ALLOCATED_BY_N8N'
};

return [{
  json: {
    ...payload,
    allocated,
    prototypeDisclaimer: 'PROTOTYPE DEMONSTRATION: External real emergency services are not connected. Dispatch actions are simulated via mock endpoints.'
  }
}];

// Trigger Drone Workflow Sub-Execution
const data = $input.first().json;

const droneMission = {
  droneCallsign: 'UAV-Echo-1',
  model: 'Matrice 300 RTK',
  missionType: 'THERMAL_SEARCH_CORRIDOR',
  targetZone: data.allocated?.priorityZone || 'Zone A',
  status: 'MISSION_CREATED',
  airborneAt: new Date().toISOString(),
  telemetryStreamActive: true
};

return [{
  json: {
    ...data,
    droneMission
  }
}];

